const FULL_PY_TABLE="yi,ding,kao,qi,shang,xia,han,wan,zhang,san,ji,bu,yu,mian,gai,chou,zhuan,qie,pi,shi,qiu,bing,ye,cong,dong,si,cheng,diu,liang,you,yan,sang,gun,jiu,ge,ya,qiang,zhong,jie,feng,guan,chuan,chan,lin,zhuo,zhu,ba,dan,wei,jing,li,ju,pie,fu,nai,wu,tuo,me,zhi,zha,hu,fa,le,yin,ping,pang,qiao,guai,mie,xi,xiang,shu,dou,nang,jia,mao,mai,luan,zi,ru,xue,sha,na,gan,suo,cui,zhe,qian,gui,jue,ma,zheng,er,chu,kui,yun,sui,gen,xie,tou,wang,kang,da,jiao,hai,heng,mu,ting,qin,bo,lian,duo,ren,shen,ze,jin,pu,reng,fo,lun,cang,zai,ta,xian,hong,tong,dai,ling,chao,chang,sa,men,fan,yang,wo,jian,yao,fen,di,fang,pei,diao,dun,xin,ai,xiu,tang,huo,hui,che,xun,nu,gu,ni,ban,xu,zhou,qu,ci,beng,ga,dian,bi,zhao,zuo,ti,zhan,he,she,gou,ning,yong,wa,ka,bao,lao,bai,ming,hen,quan,tiao,xing,kan,lai,chi,kua,guang,mi,an,lu,mou,cha,gong,cun,lv,zhen,ce,kuai,chai,nong,hou,jiong,tui,nan,xiao,bian,cu,e,ku,jun,zu,hun,su,lia,pai,biao,fei,bei,zong,tian,dao,tan,chui,peng,kong,juan,luo,song,leng,ben,cai,zhai,qing,ying,ruan,chun,ruo,pian,sheng,huang,duan,ou,za,lou,sou,yuan,rong,jiang,bang,hao,shan,bin,nuo,can,lei,zao,ao,chuang,piao,man,zun,liao,tie,seng,min,sai,dang,xuan,tai,lan,meng,qiong,lie,kuang,zan,chen,teng,long,rang,xiong,chong,dui,ke,tu,?,nei,liu,shou,ran,gang,gua,kou,pan,qia,mei,zhun,cou,du,kai,deng,wen,hua,yue,bie,pao,geng,shua,cuo,la,pou,tuan,mo,keng,shao,gao,lang,weng,tao,nao,zang,suan,nian,shuai,ang,que,zui,rou,shuang,die,rui,po,mang,tun,fou,shun,guo,pen,ne,m,huai,pin,ha,yo,o,shuo,huan,nou,ken,a,chuai,pa,se,nie,wai,miao,n,cao,de,hei,ceng,hm,ca,chuo,zen,lo,nin,kun,qun,ri,lve,zhui,hang,sao,zeng,zhuang,en,zou,nv,nuan,niu,rao,niang,niao,nen,sun,kuan,cen,cuan,shui,kuo,te,re,zei,den,zhua,shuan,zhuai,rua,zuan,shai,sen,run,chua,nve,gei,neng,fiao,ei,miu,eng,nun";
const FULL_PY_IDX_B64="";

let FULL_PY_IDX = null;
let FULL_PY = [];
try {
  const _b = Uint8Array.from(atob(FULL_PY_IDX_B64), c => c.charCodeAt(0));
  FULL_PY_IDX = new Uint16Array(_b.buffer);
  FULL_PY = FULL_PY_TABLE.split(",");
} catch(e) {}

function toPinyinFull(text) {
  if (!FULL_PY_IDX) return '';
  let r = '';
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    if (c >= 0x4E00 && c <= 0x9FFF) r += FULL_PY[FULL_PY_IDX[c - 0x4E00]] || '';
  }
  return r;
}

function toPinyinFL(text) {
  let r = '';
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    if (c >= 0x4E00 && c <= 0x9FFF) r += PINYIN_PHONE[c] || PINYIN_MAP[c - 0x4E00] || '';
  }
  return r.toLowerCase();
}

function isSubsequence(short, long) {
  let si = 0;
  for (const ch of long) { if (ch === short[si] && ++si === short.length) return true; }
  return false;
}

function fuzzyVariants(py) {
  const r = [];
  r.push(py.replace(/zh/g,'z'), py.replace(/ch/g,'c'), py.replace(/sh/g,'s'));
  r.push(py.replace(/z(?!h)/g,'zh'), py.replace(/c(?!h)/g,'ch'), py.replace(/s(?!h)/g,'sh'));
  r.push(py.replace(/n/g,'l'), py.replace(/l/g,'n'));
  r.push(py.replace(/ng/g,'n'), py.replace(/n(?![gh])/g,'ng'));
  r.push(py.replace(/ang/g,'an'), py.replace(/eng/g,'en'), py.replace(/ing/g,'in'));
  r.push(py.replace(/an(?!g)/g,'ang'), py.replace(/en(?!g)/g,'eng'), py.replace(/in(?!g)/g,'ing'));
  r.push(py.replace(/iang/g,'ian'), py.replace(/uang/g,'uan'));
  r.push(py.replace(/ian(?!g)/g,'iang'), py.replace(/uan(?!g)/g,'uang'));
  return r.filter(v => v && v !== py);
}

// 本地搜索历史联想打分:返回 null(不匹配)或 { score, first, hits }
// score 越大匹配质量越高;first 为首个命中下标(拼音命中为 -1);hits 为原文命中区间,仅文本命中时返回用于高亮
function scorePinyinMatch(item, filter) {
  try {
    const f = filter.toLowerCase().replace(/[^a-z0-9一-鿿]/g, '');
    const il = item.toLowerCase();
    if (!f) return { score: 0, first: -1, hits: [] };

    // 子序列命中位点:返回 long 中匹配下标数组,非子序列返回 null
    function subseqPos(short, long) {
      let si = 0, pos = [];
      for (let i = 0; i < long.length && si < short.length; i++) {
        if (long[i] === short[si]) { pos.push(i); si++; }
      }
      return si === short.length ? pos : null;
    }
    // 紧密度加分:命中跨度越小越接近连续(上限 +10)
    const tightness = (pos) => Math.round(10 * f.length / (pos[pos.length - 1] - pos[0] + 1));

    // 1) 原文文本匹配(可返回 hits 高亮)
    if (il === f) return { score: 1000, first: 0, hits: [[0, il.length]] };
    if (il.startsWith(f)) return { score: 900, first: 0, hits: [[0, f.length]] };
    {
      const idx = il.indexOf(f);
      if (idx >= 0) return { score: 800, first: idx, hits: [[idx, idx + f.length]] };
    }
    {
      const pos = subseqPos(f, il);
      if (pos) return { score: 700 + tightness(pos), first: pos[0], hits: [[pos[0], pos[pos.length - 1] + 1]] };
    }

    // 2) 拼音简拼/全拼匹配(命中不高亮)
    const pyFL = toPinyinFL(item);
    if (pyFL) {
      if (pyFL.startsWith(f)) return { score: 600, first: -1, hits: [] };
      {
        const pos = subseqPos(f, pyFL);
        if (pos) return { score: 550 + tightness(pos), first: -1, hits: [] };
      }
    }
    const fullPy = toPinyinFull(item);
    if (fullPy) {
      if (fullPy.startsWith(f)) return { score: 480, first: -1, hits: [] };
      {
        const pos = subseqPos(f, fullPy);
        if (pos) return { score: 440 + tightness(pos), first: -1, hits: [] };
      }
    }

    // 3) 模糊音(zh↔z 等)子序列匹配
    if (pyFL || fullPy) {
      for (const v of fuzzyVariants(f)) {
        if (!v) continue;
        if (pyFL && isSubsequence(v, pyFL)) return { score: 400, first: -1, hits: [] };
        if (fullPy && (fullPy.startsWith(v) || isSubsequence(v, fullPy))) return { score: 400, first: -1, hits: [] };
      }
    }
  } catch(e) {}
  return null;
}
